window.DCI_TOOL_VIEW = (() => {
  const names=['snort','zeek','arkime'];
  const numbers={snort:'01',zeek:'02',arkime:'03'};
  const text={en:{tools:'Network tools',review:'Reviewed: 6 November 2026',scope:'Public-source teaching material. Configuration examples require an approved, compatible lab; they are not organisational baselines.',sources:'Sources and version scope',downloads:'Practice files',pcapNote:'Synthetic examples, not incident evidence. Fixed time: 1 November 2026, 12:00 UTC. Expected tool results are explained separately from verified file construction.',full:'Open full-size screenshot',next:'Next chapter',back:'All lessons',steps:'Read the screenshot',labNotes:'Lab notes and hashes',rules:'Snort practice rule'},ko:{tools:'네트워크 도구',review:'확인일: 2026년 11월 6일',scope:'공개 자료를 바탕으로 한 교육 자료입니다. 구성 예시는 승인된 호환 실습 환경에서 검토해야 하며 조직의 기준 구성을 뜻하지 않습니다.',sources:'출처와 적용 버전',downloads:'실습 파일',pcapNote:'실제 사고 증거가 아닌 자체 제작한 예제입니다. 고정 시각: 2026년 11월 1일 12:00 UTC. 파일 생성·검증과 도구 실행의 예상 결과를 구분해 설명합니다.',full:'스크린샷 원본 크기로 보기',next:'다음 강의',back:'전체 강의',steps:'화면에서 확인할 위치',labNotes:'실습 안내와 해시',rules:'Snort 실습 규칙'}};
  const photos={
    'arkime-sessions':{file:'arkime-sessions.webp',full:'https://arkime.com/assets/sessions.png',url:'https://arkime.com/#screenshots',title:{en:'Arkime Sessions · official v5.0.0 screenshot',ko:'Arkime Sessions · 공식 v5.0.0 화면'},note:{en:'Published by the Arkime project. Historical interface and demonstration data; not the downloadable lab result.',ko:'Arkime 프로젝트가 공개한 과거 버전의 실제 화면과 예시 데이터입니다. 내려받는 실습 파일의 실행 결과가 아닙니다.'}},
    'arkime-session-detail':{file:'arkime-session-detail.webp',full:'https://arkime.com/assets/session-detail.png',url:'https://arkime.com/',title:{en:'Arkime session details · official screenshot',ko:'Arkime 세션 상세 · 공식 화면'},note:{en:'Upstream screenshot accompanying the v5-era interface. Inspect endpoints, session fields and captured data. Menu details differ by release.',ko:'프로젝트의 v5 시기 화면 자료입니다. 양 끝점·세션 필드·수집 내용을 살펴보세요. 세부 메뉴는 버전마다 다릅니다.'}},
    'arkime-spiview':{file:'arkime-spiview.webp',full:'https://arkime.com/assets/spiview.png',url:'https://arkime.com/#screenshots',title:{en:'Arkime SPI View · official v5.0.0 screenshot',ko:'Arkime SPI View · 공식 v5.0.0 화면'},note:{en:'Upstream example of indexed-field summaries. Counts and addresses are demonstration data, not indicators from this course.',ko:'색인 필드 요약을 보여주는 공식 예시입니다. 수량과 주소는 이 과정에서 발견한 위협 지표가 아닙니다.'}},
    'zeek-playground':{file:'zeek-playground.png',url:'https://try.zeek.org/',title:{en:'Try Zeek · actual hosted editor',ko:'Try Zeek · 실제 공식 웹 실습장'},note:{en:'Captured during this update with Zeek 9.0.1 and the built-in http.pcap selected. This shows the editor and controls before execution, not verified analysis output or a native Zeek GUI.',ko:'이번 업데이트에서 Zeek 9.0.1과 내장 http.pcap을 선택한 실제 웹 화면입니다. 실행 전 편집기·설정 화면이며, 검증된 분석 출력이나 Zeek 기본 GUI가 아닙니다.'}},
    'snort-alerts-splunk':{file:'snort-alerts-splunk.png',url:'https://snort-org-site.s3.amazonaws.com/production/document_files/files/000/012/147/original/Snort_3.1.8.0_on_Ubuntu_18_and_20.pdf',title:{en:'Searching Snort JSON alerts in Splunk · historical screenshot',ko:'Splunk에서 Snort JSON 경보 검색 · 과거 실제 화면'},note:{en:'Noah Dietrich, Snort 3.1.18.0 on Ubuntu 18 & 20 (2021-12-30), p.20. CC BY-NC-SA 4.0; original embedded PNG, unchanged. This is Splunk Search & Reporting, not a native Snort GUI. No returned alert events are shown.',ko:'Noah Dietrich, Snort 3.1.18.0 on Ubuntu 18 & 20(2021-12-30), 20쪽. CC BY-NC-SA 4.0, 원본 PNG를 변경 없이 추출했습니다. Snort 기본 GUI가 아닌 Splunk 검색 화면이며 검색 결과 경보는 보이지 않습니다.'}}
  };
  function screenshot(key,lang){
    const p=photos[key],src='./assets/screenshots/'+p.file,full=p.full||src;
    return `<figure class="tool-screenshot"><figcaption>${p.title[lang]}</figcaption><a href="${full}" target="_blank" rel="noopener noreferrer" aria-label="${text[lang].full}"><img src="${src}" alt="${p.title[lang]}" loading="eager" decoding="async"></a><p>${p.note[lang]}${p.full?(lang==='ko'?' 웹용 축소 미리보기이며, 원본 크기 링크에서 공식 PNG를 열 수 있습니다.':' This is a scaled web preview; the full-size link opens the official original PNG.'):''}</p><div class="screenshot-links"><a href="${full}" target="_blank" rel="noopener noreferrer">${text[lang].full}</a><a href="${p.url}" target="_blank" rel="noopener noreferrer">${lang==='ko'?'출처':'Source'}</a>${key==='snort-alerts-splunk'?'<a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-NC-SA 4.0</a>':''}</div></figure>`;
  }
  function diagram(title,steps,note,lang){
    const h=steps.length*83+8;
    const elements=steps.map((s,i)=>{
      const y=8+i*83;const lines=s.split('|');
      return `<rect x="30" y="${y}" width="280" height="60" rx="5"/>${lines.map((line,j)=>`<text x="170" y="${y+35+(j-(lines.length-1)/2)*20}" text-anchor="middle">${line}</text>`).join('')}${i<steps.length-1?`<path class="flow-arrow" d="M170 ${y+62}v18m-5-5 5 5 5-5"/>`:''}`;
    }).join('');
    return `<figure class="learning-figure tool-diagram"><figcaption>${title}</figcaption><svg class="diagram" viewBox="0 0 340 ${h}" role="img" aria-label="${steps.join(' → ').replaceAll('|',' ')}"><title>${title}</title>${elements}</svg><p class="figure-note">${note}</p></figure>`;
  }
  function architecture(lang){
    const ko=lang==='ko';
    return `<figure class="learning-figure arkime-architecture"><figcaption>${ko?'그림. Arkime의 메타데이터 경로와 패킷 경로':'Figure. Arkime metadata and packet paths'}</figcaption><svg class="diagram" viewBox="0 0 360 420" role="img" aria-label="${ko?'Capture는 원본을 PCAP에, 세션 정보를 색인에 기록합니다. Viewer는 검색과 패킷 조회를 각각 수행합니다.':'Capture writes PCAP and session indexes separately. Viewer uses the index to search and the packet path to retrieve bytes.'}"><rect x="80" y="8" width="200" height="58" rx="5"/><text x="180" y="43" text-anchor="middle">Capture</text><path class="flow-arrow" d="M120 68v49m-5-5 5 5 5-5M240 68v49m-5-5 5 5 5-5"/><rect x="8" y="122" width="165" height="75" rx="5"/><rect x="187" y="122" width="165" height="75" rx="5"/><text x="90" y="153" text-anchor="middle">${ko?'원본 패킷':'Raw packets'}</text><text x="90" y="178" text-anchor="middle">PCAP</text><text x="270" y="153" text-anchor="middle">${ko?'세션 메타데이터':'Session metadata'}</text><text x="270" y="178" text-anchor="middle">${ko?'색인 DB':'Index database'}</text><path class="flow-arrow" d="M270 200v44h-90v43m-5-5 5 5 5-5"/><path class="feedback-arrow" d="M90 200v112h19m-5-5 5 5-5 5"/><text x="65" y="250" text-anchor="middle">${ko?'패킷':'Packet'}</text><text x="65" y="272" text-anchor="middle">${ko?'조회':'retrieval'}</text><rect x="112" y="292" width="180" height="67" rx="5"/><text x="202" y="330" text-anchor="middle">Viewer</text><text x="180" y="397" text-anchor="middle">${ko?'색인 정상 ≠ PCAP 보관 보장':'Healthy index ≠ retained PCAP'}</text></svg><p class="figure-note">${ko?'논리적 경로를 단순화했습니다. 실제 패킷 전달에는 해당 센서 Viewer와 인증·연결 설정이 필요합니다.':'Logical paths are simplified. Retrieval also depends on the appropriate sensor viewer, connectivity and authentication.'}</p></figure>`;
  }
  function figures(id,section,lang){
    const ko=lang==='ko';
    if(id==='snort'&&section==='gateway')return diagram(ko?'그림. 수동형 Snort의 입력 경로':'Figure. Passive Snort input path',ko?['실제 통신 링크','TAP / SPAN|선정한 통신 복사','Snort / DAQ|검사와 규칙 평가','경보 → 패킷 확인|호스트 조사와 연결']:['Live traffic link','TAP / SPAN|Selected traffic copies','Snort / DAQ|Inspection and rules','Alert → packet review|Correlate host evidence'],ko?'복사본을 검사하므로 수동형 센서 자체가 원래 통신을 차단하지는 않습니다.':'Inspecting a copy does not let a passive sensor block the original traffic.',lang);
    if(id==='snort'&&section==='configure')return diagram(ko?'그림. 변경을 검증하는 순서':'Figure. Validate a detection change',ko?['임무·가설·관측 범위','변수·검사·규칙 설정','구성 검사 → PCAP 시험','정상 대조군 → 성능 확인','승인된 적용·복구·평가']:['Mission and hypothesis','Variables, inspectors, rules','Config test → PCAP test','Negative controls, performance','Approved rollout and review'],ko?'문법 검사 통과와 실제 탐지 성공은 별도입니다.':'A valid configuration and an effective detection are separate checks.',lang);
    if(id==='snort'&&section==='interpret')return screenshot('snort-alerts-splunk',lang);
    if(id==='snort'&&section==='snort2-deploy')return diagram(ko?'그림. Snort 2 규칙을 적용하는 순서':'Figure. Applying a Snort 2 rule',ko?['local.rules에 규칙 추가','snort -T|규칙 수와 오류 확인','PCAP 시험 (-r)|내 sid가 보이나요?','실시간 시험 (-i)|격리된 실습망','검사 → 재시작 → 경보 확인']:['Add the rule to local.rules','snort -T|Rule count and errors','PCAP test (-r)|Is your sid in the alert?','Live test (-i)|Isolated lab segment','Validate → restart → watch alerts'],ko?'각 단계를 통과해야 다음 단계로 갑니다. 검사를 건너뛰고 재시작하면 센서가 멈출 수 있어요.':'Pass each step before the next. Restarting without validating can stop the sensor.',lang);
    if(id==='zeek'&&section==='2')return diagram(ko?'그림. Zeek 안팎의 데이터 흐름':'Figure. Data flow through and beyond Zeek',ko?['인터페이스 / PCAP','프로토콜·세션·파일 분석','이벤트 → 스크립트·프레임워크','구조화된 로그','수집기 → SIEM']:['Interface / PCAP','Protocol, session, file analysis','Events → scripts / frameworks','Structured log streams','Collector → SIEM'],ko?'Zeek의 패킷 입력과 SIEM의 로그 입력은 서로 다른 단계입니다. 전체 PCAP 보관도 별도로 설계합니다.':'Packet ingestion and log ingestion are different stages. Full PCAP retention is a separate design.',lang);
    if(id==='zeek'&&section==='5')return screenshot('zeek-playground',lang)+`<p>${ko?'공식 웹 실습장에서는 예제를 선택하고 버전·PCAP을 지정한 뒤 Run을 누릅니다. 실행이 완료되면 출력과 로그 탭을 확인하세요. 이 캡처에서는 실행 결과를 검증하지 못했으므로 화면을 분석 성공의 증거로 사용하지 않습니다.':'In the official playground, choose an example, version and PCAP, then Run. After a successful run, inspect output and log tabs. No successful analysis output was verified for this screenshot; it is an interface walkthrough.'}</p>`;
    if(id==='zeek'&&section==='11')return diagram(ko?'그림. 로그 전달을 검증하는 지점':'Figure. Check each log-delivery boundary',ko?['센서 로그가 실제 생성됐나요?','파일 회전 뒤에도 읽나요?','필드·시간·UID를 유지했나요?','SIEM 도착·지연·검색 확인']:['Was the sensor log created?','Does collection survive rotation?','Preserve fields, time and UID','Verify SIEM arrival and search'],ko?'도착하지 않은 로그와 검색 조건에 맞지 않는 로그를 구분합니다.':'Distinguish missing delivery from a search mismatch.',lang);
    if(id==='arkime'&&section==='architecture')return architecture(lang);
    if(id==='arkime'&&section==='fault-path')return diagram(ko?'그림. 검색 실패와 패킷 조회 실패 구분':'Figure. Separate search and packet failures',ko?['시간·검색 조건 확인','색인·권한·스키마 확인','세션이 있으면 패킷 경로 확인','파일·보존·센서 연결 확인']:['Check time and expression','Check index, access, schema','If session exists, follow PCAP path','Check file, retention, sensor'],ko?'세션 검색과 원본 패킷 조회는 같은 검사가 아닙니다.':'Session search and raw-packet retrieval are different checks.',lang);
    return '';
  }
  function downloads(id,lang){
    const file=id==='snort'?'dci-winrm.pcap':'dci-http-dns.pcap';
    return `<aside class="lab-downloads"><h2>${text[lang].downloads}</h2><p>${text[lang].pcapNote}</p><div><a href="./assets/labs/${file}" download>${file}</a>${id==='snort'?`<a href="./assets/labs/dci-local.rules" download>${text[lang].rules}</a><a href="./assets/labs/dci-smb-samr.pcap" download>dci-smb-samr.pcap</a><a href="./assets/labs/dci-smb-samr-badsum.pcap" download>dci-smb-samr-badsum.pcap</a><a href="./assets/labs/dci-snort2-local.rules" download>${lang==='ko'?'Snort 2 실습 규칙':'Snort 2 practice rules'}</a>`:''}<a href="./assets/labs/README.txt" download>${lang==='ko'?'실습 안내':'Lab notes'}</a><a href="./assets/labs/manifest.json" download>SHA-256</a></div></aside>`;
  }
  function render(id,lang){
    const c=window.DCI_CHAPTERS[id];
    let body=c.sections.map((s,i)=>`<section id="${id}-${s.id}"><h2>${i+1}. ${s.title[lang]}</h2>${s.html[lang]}${figures(id,s.id,lang)}</section>`).join('');
    body=body.replace(/<div data-screenshot="([^"]+)"><\/div>/g,(_,key)=>screenshot(key,lang));
    const references=c.sources.map((r,i)=>`<li><a href="${r.url}" target="_blank" rel="noopener noreferrer">${typeof r.title==='object'?r.title[lang]:r.title}</a></li>`).join('');
    const next=names[names.indexOf(id)+1];
    return `<article class="overview-article tool-chapter"><div class="article-meta"><span>${text[lang].tools} / ${numbers[id]}</span><span>${text[lang].review}</span></div><p class="chapter-scope">${text[lang].scope}</p>${downloads(id,lang)}<nav class="article-toc" aria-label="${lang==='ko'?'이 강의의 목차':'Chapter contents'}"><h2>${lang==='ko'?'이 강의에서 다룰 내용':'In this chapter'}</h2><ol>${c.sections.map((s,i)=>`<li><a href="#${id}-${s.id}" data-scroll="${id}-${s.id}">${s.title[lang]}</a></li>`).join('')}</ol></nav><div class="article-body">${body}<section class="sources-section"><h2>${text[lang].sources}</h2><p>${c.version}</p><ol class="source-list">${references}</ol></section></div><nav class="chapter-pagination"><a href="#lessons">← ${text[lang].back}</a>${next?`<a href="#${next}">${text[lang].next}: ${next==='zeek'?'Zeek':'Arkime'} →</a>`:''}</nav></article>`;
  }
  function cards(lang){return names.map(id=>`<a href="#${id}" class="lesson-entry"><span class="lesson-index">${numbers[id]}</span><span class="lesson-entry-body"><span class="lesson-label">${text[lang].tools}</span><h2>${window.DCI_CHAPTERS[id].title[lang]}</h2><span class="lesson-summary">${window.DCI_CHAPTERS[id].subtitle[lang]}</span></span><svg class="icon" aria-hidden="true"><use href="#icon-arrow"/></svg></a>`).join('');}
  return {render,cards};
})();
